"💡 Актау стоит на берегу Каспийского моря": "💡 Ақтау Каспий теңізінің жағасында тұр",
"💡 Алматы — самый большой город Казахстана": "💡 Алматы — Қазақстанның ең үлкен қаласы",
"💡 Аль-Фараби был великим учёным, его назвали «Вторым учителем»": "💡 Әл-Фараби ұлы ғалым болған, оны «Екінші ұстаз» деп атаған",
"💡 Аль-Фараби родился в Фарабе — так раньше называли город Отрар": "💡 Әл-Фараби Фарабта дүниеге келген — бұрын Отырар қаласы осылай аталған",
"💡 Астана — столица Казахстана. Она находится в центре страны, на реке Есиль": "💡 Астана — Қазақстанның астанасы. Ол елдің ортасында, Есіл өзенінің бойында орналасқан",
"💡 Ботайская культура — культура древних людей на севере Казахстана": "💡 Ботай мәдениеті — Қазақстанның солтүстігіндегі ежелгі адамдардың мәдениеті",
"💡 Ботайцы считаются одними из первых в мире, кто приручил лошадь": "💡 Ботайлықтар жылқыны әлемде алғаш қолға үйреткендердің бірі болып саналады",
"💡 Бурабай — красивый курорт с лесом и озёрами в Акмолинской области": "💡 Бурабай — Ақмола облысындағы орманы мен көлдері бар әдемі курорт",
"💡 В День Победы вспоминают тех, кто защищал страну в Великой Отечественной войне": "💡 Жеңіс күні Ұлы Отан соғысында елді қорғағандарды еске алады",
"💡 В библиотеке помогают найти нужную книгу": "💡 Кітапханада қажетті кітапты табуға көмектеседі",
"💡 В горах быстро меняется погода и нужны вода и удобная обувь": "💡 Тауда ауа райы тез өзгереді, су мен ыңғайлы аяқ киім керек",
"💡 В горах добывают руду, зимой копится снег, весной он питает реки": "💡 Тауда кен өндіреді, қыста қар жиналады, көктемде ол өзендерді қоректендіреді",
"💡 В грозу прячутся в доме: молния попадает в высокие предметы": "💡 Найзағай кезінде үйде тығылады: найзағай биік заттарға түседі",
"💡 В декабре мы празднуем независимость нашей страны": "💡 Желтоқсанда біз еліміздің тәуелсіздігін тойлаймыз",
"💡 В нашей стране в полдень Солнце стоит на юге": "💡 Біздің елде түсте Күн оңтүстікте тұрады",
"💡 В семейном архиве хранят старые фотографии, письма и документы": "💡 Отбасылық мұрағатта ескі фотосуреттер, хаттар және құжаттар сақталады",
"💡 В словесном портрете рассказывают о внешности и характере человека": "💡 Сөзбен жасалған портретте адамның сырт келбеті мен мінезі туралы айтады",
"💡 В этот день отмечают дружбу народов нашей страны": "💡 Бұл күні еліміздегі халықтардың достығы аталып өтеді",
"💡 В этот день отмечают дружбу народов страны": "💡 Бұл күні елдегі халықтардың достығы аталып өтеді",
"💡 Верно. Ботайцы охотились на лошадей и приручали их": "💡 Дұрыс. Ботайлықтар жылқы аулап, оларды қолға үйреткен",
"💡 Верно. В коллективе люди делают общее дело и помогают друг другу": "💡 Дұрыс. Ұжымда адамдар ортақ іс істеп, бір-біріне көмектеседі",
"💡 Верно. В них много витаминов": "💡 Дұрыс. Оларда дәрумендер көп",
"💡 Верно. В тумане плохо видно дорогу": "💡 Дұрыс. Тұманда жол нашар көрінеді",
"💡 Верно. Вежливость и уважение нужны везде: и в школе, и на улице, и в магазине": "💡 Дұрыс. Сыпайылық пен құрмет барлық жерде керек: мектепте де, көшеде де, дүкенде де",
